  .index-hero-content {
    order: 2;
  }

  .index-hero-image {
    order: 1;
  }

  .index-hero-subtitle {
    font-size: 1rem;
  }

  .index-cta-primary {
    width: 100%;
  }

  .index-benefit-item {
    padding: var(--spacing-md);
  }

  .index-cta-secondary {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .index-hero {
    padding: var(--spacing-xxl) 0;
  }

  .index-features,
  .index-testimonials {
    padding: var(--spacing-xxl) 0;
  }
}
